/*
 * Layout option metadata for editor completion and hovers, DOM-free: `knownLayoutOptions()` and
 * `knownLayoutAlgorithms()` of the elk-lean API (ids, names, groups, types, targets, supported
 * options) plus the enum literals of ENUM / ENUMSET options, which the elkjs-compatible API does
 * not report; they come from `elk options --choices` (src/generated/option-choices.json,
 * regenerated by `npm run gen:choices`).
 *
 * SPDX-License-Identifier: EPL-2.0 OR GPL-3.0-or-later
 */

export interface OptionInfo {
  id: string;
  /** the id without `org.eclipse.` (what the app inserts: `elk.direction`) */
  shortId: string;
  name: string;
  description: string;
  group: string;
  type: string;
  targets: string[];
  choices: string[];
}

export interface AlgorithmInfo {
  id: string;
  shortId: string;
  name: string;
  description: string;
  knownOptions: string[];
}

export interface Metadata {
  options: OptionInfo[];
  algorithms: AlgorithmInfo[];
}

type Raw = Record<string, unknown>;

const strip = (id: string): string => (id.startsWith('org.eclipse.') ? id.substring('org.eclipse.'.length) : id);
const str = (v: unknown): string => (typeof v === 'string' ? v : '');
const strs = (v: unknown): string[] => (Array.isArray(v) ? v.map(String) : []);

export function buildMetadata(options: Raw[], algorithms: Raw[], choices: Record<string, string[]>): Metadata {
  return {
    options: options.map((o) => ({
      id: str(o.id),
      shortId: strip(str(o.id)),
      name: str(o.name),
      description: str(o.description),
      group: str(o.group),
      type: str(o.type),
      targets: strs(o.targets),
      choices: choices[str(o.id)] ?? strs(o.choices),
    })).sort((a, b) => a.shortId.localeCompare(b.shortId)),
    algorithms: algorithms.map((a) => ({
      id: str(a.id),
      shortId: strip(str(a.id)).replace(/^elk\./, ''),
      name: str(a.name),
      description: str(a.description),
      knownOptions: strs(a.knownOptions),
    })),
  };
}

/**
 * The option a key written in ELK Text denotes: ELK resolves a key by exact id or by suffix after a
 * dot (`direction`, `elk.direction`, `org.eclipse.elk.direction`); the shortest matching id wins.
 */
export function resolveOption(meta: Metadata, key: string): OptionInfo | undefined {
  let best: OptionInfo | undefined;
  for (const o of meta.options) {
    if (o.id === key || o.id.endsWith('.' + key)) {
      if (!best || o.id.length < best.id.length) best = o;
    }
  }
  return best;
}

/** The algorithm an `algorithm:` value denotes (`layered`, `elk.layered`, full id). */
export function resolveAlgorithm(meta: Metadata, value: string): AlgorithmInfo | undefined {
  const v = value.replace(/^"|"$/g, '');
  return meta.algorithms.find((a) => a.id === v || a.id.endsWith('.' + v));
}

/** ELK Text element kinds and the option targets that apply to them. */
export type ElementKind = 'root' | 'node' | 'port' | 'edge' | 'label';
export const TARGETS: Record<ElementKind, string[]> = {
  root: ['PARENTS'],
  node: ['NODES', 'PARENTS'],
  port: ['PORTS'],
  edge: ['EDGES'],
  label: ['LABELS'],
};

export interface Context {
  /** element whose property block the cursor is in */
  element: ElementKind;
  /** inside `layout [ ... ]` or an edge section (no options there) */
  inLayoutBlock: boolean;
  /** `algorithm:` values of the enclosing scopes, innermost first */
  algorithms: string[];
}

/**
 * Scans ELK Text up to the cursor (ignoring strings and comments) for the innermost `node`/`port`/
 * `edge`/`label` block and the `algorithm:` settings of the enclosing blocks.
 */
export function contextAt(text: string): Context {
  const stack: { kind: ElementKind | 'other'; algorithm?: string }[] = [{ kind: 'root' }];
  let lastKeyword: ElementKind | 'other' = 'other';
  let bracket = 0;
  let i = 0;
  const n = text.length;
  while (i < n) {
    const c = text[i];
    if (c === '/' && text[i + 1] === '/') {
      while (i < n && text[i] !== '\n') i++;
      continue;
    }
    if (c === '/' && text[i + 1] === '*') {
      const e = text.indexOf('*/', i + 2);
      i = e < 0 ? n : e + 2;
      continue;
    }
    if (c === '"' || c === "'") {
      i++;
      while (i < n && text[i] !== c) i += text[i] === '\\' ? 2 : 1;
      i++;
      continue;
    }
    if (/[A-Za-z_$]/.test(c)) {
      let j = i;
      while (j < n && /[\w$.]/.test(text[j])) j++;
      const word = text.substring(i, j);
      if (word === 'node' || word === 'port' || word === 'edge' || word === 'label') lastKeyword = word;
      else if (word === 'graph') lastKeyword = 'root';
      else if (word === 'algorithm' || word.endsWith('.algorithm')) {
        const m = /^\s*:\s*("?)([\w.]+)\1/.exec(text.substring(j));
        if (m) stack[stack.length - 1].algorithm = m[2];
      }
      i = j;
      continue;
    }
    if (c === '[') bracket++;
    else if (c === ']') bracket = Math.max(0, bracket - 1);
    else if (c === '{') {
      stack.push({ kind: bracket > 0 ? 'other' : lastKeyword });
      lastKeyword = 'other';
    } else if (c === '}') {
      if (stack.length > 1) stack.pop();
    }
    i++;
  }
  let element: ElementKind = 'root';
  let inLayoutBlock = bracket > 0;
  for (let k = stack.length - 1; k >= 0; k--) {
    const kind = stack[k].kind;
    if (kind === 'other') {
      inLayoutBlock = true;
      continue;
    }
    element = kind;
    break;
  }
  const algorithms = stack.slice().reverse().map((s) => s.algorithm).filter((a): a is string => !!a);
  return { element, inLayoutBlock, algorithms };
}
